  const brandNodes=[...document.querySelectorAll("[data-brand-links]")];
  brandNodes.forEach(el=>{ if(!el.dataset.brandSource) el.dataset.brandSource=el.textContent; });
  function restoreBrandSources(){ brandNodes.forEach(el=>{ el.textContent=el.dataset.brandSource; }); }
  function linkBrands(){
    const specs=[
      {label:"RAILWAYAUTOMATIC®",href:"https://railwayautomatic.com/"},
      {label:"RWA®",href:"https://rwa.ua/"}
    ];
    brandNodes.forEach(el=>{
      const walker=document.createTreeWalker(el,NodeFilter.SHOW_TEXT); const nodes=[];
      while(walker.nextNode()) nodes.push(walker.currentNode);
      nodes.forEach(node=>{
        const text=node.nodeValue; if(!specs.some(s=>text.includes(s.label))) return;
        const frag=document.createDocumentFragment(); let rest=text;
        while(rest){
          let hit=null,at=rest.length;
          specs.forEach(s=>{ const i=rest.indexOf(s.label); if(i>=0&&i<at){at=i;hit=s;} });
          if(!hit){frag.append(rest);break;}
          if(at) frag.append(rest.slice(0,at));
          const a=document.createElement("a"); a.href=hit.href; a.target="_blank"; a.rel="noopener"; a.textContent=hit.label; frag.append(a);
          rest=rest.slice(at+hit.label.length);
        }
        node.replaceWith(frag);
      });
    });
  }
